import type { HistoricalEvent } from "@/types/history";

// ── The Republic conquers Italy, 509–265 BCE ────────────────────────────────
//
// These entries are mostly phases rather than years, and that is the honest shape
// of the material. From 264 Polybius supports a year at a time; for the fifth
// century what survives is a list of consuls, a scatter of triumphs, and wars
// described in language borrowed from later ones. Livy himself says the records
// were thin and that much was lost when the Gauls burned the city.
//
// So a decade of Volscian raiding is one entry covering the decade, and single
// years are used only where something specific is fixed to one. Nothing is padded
// out to fill the scrubber, and almost everything before 390 carries the
// `traditional` grade: this is what Rome remembered, not what can be shown.
const earlyRepublicEvents: HistoricalEvent[] = [
  { id: "e509", year: -509, title: "The kings expelled", summary: "Tarquinius Superbus is driven out and the Republic begins with two annual magistrates in place of a king. Within a year or two, on Polybius' reckoning — he dates it by the first consuls and by Xerxes' crossing, which puts it at 508 or 507 — Rome makes a treaty with Carthage. Polybius says he read it himself off bronze in the treasury, which is what makes it the earliest document in Roman history.", certainty: "traditional", war: "early-republic" },
  { id: "e508", year: -508, toYear: -505, title: "The Etruscan attempt to restore the Tarquins", summary: "Lars Porsenna of Clusium marches on Rome for the exiled king. The tradition turns the campaign into a series of heroic set pieces — Horatius at the bridge, Mucius Scaevola in the enemy camp — which is a sign that what really happened had already been lost.", certainty: "traditional", war: "early-republic" },
  { id: "e504", year: -504, toYear: -497, title: "Latium divided over Rome", summary: "The Latin cities will not accept that a Rome without kings still leads them. Both sides look for allies, and the Sabine and Etruscan borders stay open.", certainty: "traditional", war: "early-republic" },
  { id: "e496", year: -496, title: "Battle of Lake Regillus", summary: "Rome defeats a Latin army in the war over the leadership of Latium. The tradition has Castor and Pollux fighting in the Roman line and watering their horses in the Forum afterwards.", certainty: "traditional", battleSlug: "lake-regillus", war: "early-republic" },
  { id: "e495", year: -495, toYear: -494, title: "The first secession of the plebs", summary: "The commons withdraw from the city over debt and military service and the war effort stops until terms are agreed. Rome's internal settlement and its capacity to fight were the same question for the next two centuries.", certainty: "traditional", war: "early-republic" },
  { id: "e493", year: -493, title: "The treaty of Cassius", summary: "Rome and the Latin cities agree a permanent alliance with shared command, shared plunder and mutual citizenship rights. It ends the war of 496 and makes Rome first among equals in Latium.", certainty: "traditional", war: "early-republic" },
  { id: "e492", year: -492, toYear: -483, title: "The Volsci and Aequi come down off the hills", summary: "Two upland peoples raid the Latin plain almost every year, and Rome fights them almost every year in return. The tradition of Coriolanus — a Roman commander who defected to the Volsci and led them against his own city — belongs here.", certainty: "traditional", war: "early-republic" },
  { id: "e482", year: -482, toYear: -478, title: "The first Veientine war", summary: "Fighting with Veii, the Etruscan city fifteen kilometres up the Tiber, over the crossing at Fidenae and the salt route to the coast.", certainty: "traditional", war: "early-republic" },
  { id: "e477", year: -477, title: "The Fabii destroyed at the Cremera", summary: "A Roman force built around one clan is ambushed and wiped out by the Veientines. The annalists record three hundred and six Fabii killed and one boy left alive, which is the kind of number a family tradition produces rather than a record.", certainty: "traditional", war: "early-republic" },
  { id: "e476", year: -476, toYear: -459, title: "Annual war on three frontiers", summary: "Veii to the north, the Aequi in the hills, the Volsci to the south. The consular lists record campaigns nearly every year, and the accounts of them are largely interchangeable.", certainty: "traditional", war: "early-republic" },
  { id: "e458", year: -458, title: "Cincinnatus and the Aequi at Mons Algidus", summary: "A Roman army is trapped by the Aequi and relieved by a dictator called from his plough, who resigns as soon as it is over. Whatever happened militarily, the story became Rome's central statement about power held briefly and given back.", certainty: "traditional", war: "early-republic" },
  { id: "e457", year: -457, toYear: -451, title: "The demand for written law", summary: "Pressure builds for the law to be published rather than held in the memory of patrician magistrates. Campaigning continues against the Aequi and Sabines throughout.", certainty: "traditional", war: "early-republic" },
  { id: "e450", year: -450, title: "The Twelve Tables", summary: "Rome's law is written down and set up in the Forum. It is the earliest Roman text later Romans could still read, and much of it concerns debt, land and the obligations that decided who served in the army.", certainty: "traditional", war: "early-republic" },

  { id: "e449", year: -449, toYear: -439, title: "The settlement after the decemvirate", summary: "The second board of ten falls and the Valerio-Horatian laws follow; intermarriage between the orders is conceded, and from 444 military tribunes with consular power can be elected in place of consuls. Fighting with the Aequi and Volsci continues throughout, and the Veientine frontier is quiet.", certainty: "traditional", war: "veientine-wars" },
  { id: "e438", year: -438, toYear: -426, title: "Fidenae changes hands", summary: "Fidenae revolts to Veii and is besieged and retaken. The tradition records a Roman commander killing the Veientine king in single combat and dedicating the spoils — one of only three such dedications in all Roman history.", certainty: "traditional", war: "veientine-wars" },
  { id: "e425", year: -425, toYear: -407, title: "Truce, and the reach for the far bank", summary: "A long truce with Veii while Rome fights the Volsci down the coast towards Anxur, which falls as the truce ends. Roman settlement pushes north of the Tiber, which makes another Veientine war a question of when.", certainty: "traditional", war: "veientine-wars" },
  { id: "e406", year: -406, toYear: -397, title: "The siege of Veii", summary: "Rome invests Veii and stays there. The tradition makes it a ten-year siege in deliberate imitation of Troy, and dates Rome's first military pay to it, because an army that does not go home for the harvest has to be fed.", certainty: "traditional", battleSlug: undefined, war: "veientine-wars" },
  { id: "e396", year: -396, title: "Veii destroyed", summary: "The city is taken, its people sold, and its territory annexed outright rather than left as an ally. Roman territory roughly doubles, and for the first time Rome is substantially larger than any of its neighbours.", certainty: "probable", battleSlug: "veii", war: "veientine-wars" },
  { id: "e395", year: -395, toYear: -392, title: "Southern Etruria absorbed", summary: "Capena and Falerii submit and the Veientine land is settled. Roman colonies go in on the far bank of the Tiber.", certainty: "traditional", war: "veientine-wars" },
  { id: "e391", year: -391, title: "The Senones move south", summary: "A Gallic war band from the Adriatic coast pushes into Etruria and besieges Clusium, which appeals to Rome. Roman envoys reportedly join in the fighting, and the Gauls turn on Rome instead.", certainty: "traditional", war: "veientine-wars" },

  { id: "e390", year: -390, title: "Disaster at the Allia, and the sack of Rome", summary: "A Roman army is destroyed eleven miles from the city and the Gauls take Rome itself, holding it until they are bought off. Only the Capitol holds out. The date is 390 in Rome's own reckoning and 387 or 386 in the Greek tradition.", certainty: "probable", battleSlug: "allia", war: "gallic-crisis" },
  { id: "e389", year: -389, toYear: -378, title: "Rebuilding, and holding Latium together", summary: "Rome's neighbours read the sack as the end of Roman power and are proved wrong within a decade: the Volsci, Etruscans and Aequi are beaten in turn, and the Latin and Hernican alliances are forced back into line.", certainty: "traditional", war: "gallic-crisis" },
  { id: "e377", year: -377, toYear: -367, title: "The Servian wall, and the last of the old quarrel", summary: "A circuit of dressed tufa four kilometres round is built — the only fourth-century Roman monument still standing in quantity — and the political settlement of 367 opens the consulship to plebeians.", certainty: "probable", war: "gallic-crisis" },
  { id: "e366", year: -366, toYear: -350, title: "Gallic raids and Etruscan wars", summary: "Further Gallic incursions are turned back, and Rome fights Tarquinii and Caere in southern Etruria. Long truces rather than conquests end each round.", certainty: "traditional", war: "gallic-crisis" },

  { id: "e349", year: -349, toYear: -344, title: "Rome reaches Campania", summary: "A Gallic raid is beaten off and a Greek fleet raids the Latin coast. In 348 Rome and Carthage renew their treaty dividing the western sea — Rome now speaks for that coast, which is the thing worth noticing about the document. Rome and Samnium already have a treaty, made in 354, and are about to discover they want the same ground in Campania.", certainty: "traditional", war: "latin-samnite-first" },
  { id: "e343", year: -343, toYear: -342, title: "The First Samnite War", summary: "Two years of fighting in Campania over Capua, ending in a negotiated peace that leaves Rome established south of Latium. Livy's battle narratives for these years are visibly modelled on later ones.", certainty: "traditional", battleSlug: undefined, war: "latin-samnite-first" },
  { id: "e341", year: -341, title: "Rome and Samnium come to terms", summary: "The war ends with the old treaty renewed. Rome keeps its Campanian connection, and the Latin cities conclude that Rome has become a power over them rather than the first among them.", certainty: "traditional", war: "latin-samnite-first" },
  { id: "e340", year: -340, title: "The Latin War: Vesuvius", summary: "Rome's own Latin and Campanian allies demand equality and, refused, go to war. At the foot of Vesuvius the consul Publius Decius Mus is said to have devoted himself and the enemy to the gods of the underworld and ridden into the Latin line to die. Weeks later the survivors are broken again at Trifanum.", certainty: "traditional", battleSlug: "vesuvius", war: "latin-samnite-first" },
  { id: "e339", year: -339, title: "The Latins fight on", summary: "With both their field armies broken the previous year, the Latin cities keep fighting city by city. Rome spends the season reducing them one at a time rather than in the field.", certainty: "traditional", war: "latin-samnite-first" },
  { id: "e338", year: -338, title: "The settlement of Latium", summary: "The Latin League is dissolved. Instead of one alliance of equals Rome imposes a web of separate treaties, some cities annexed with citizenship, others tied individually to Rome and forbidden to deal with each other. This system, not any battle, is what made Roman Italy.", certainty: "probable", war: "latin-samnite-first" },
  { id: "e337", year: -337, toYear: -328, title: "Colonies, roads and the Campanian frontier", summary: "Rome plants colonies at the mouths of the Apennine valleys and secures the Volscian coast. The Samnites watch the same passes from the other side.", certainty: "probable", war: "latin-samnite-first" },

  { id: "e327", year: -327, toYear: -322, title: "The Second Samnite War opens", summary: "War resumes over Neapolis and the Liris valley. Rome fights in mountain country that suits its enemy, against a federation that can raise armies as good as its own.", certainty: "probable", war: "samnite-second" },
  { id: "e321", year: -321, title: "The Caudine Forks", summary: "Two consular armies march into a closed valley, find both exits blocked, and surrender without a battle. The whole force passes under the yoke and Rome accepts terms — the most complete humiliation in Roman military history before Cannae.", certainty: "probable", battleSlug: "caudine-forks", war: "samnite-second" },
  { id: "e320", year: -320, toYear: -316, title: "Rome repudiates the peace and rearms", summary: "The senate disowns the Caudine agreement and returns the officers who guaranteed it. Roman practice changes in these years — the manipular legion, the shorter sword, colonies as fortresses — although how much was learned here and how much later is argued.", certainty: "probable", war: "samnite-second" },
  { id: "e315", year: -315, title: "Defeat at Lautulae", summary: "A Samnite victory on the coast road near Tarracina cuts Rome from Campania and brings the war to the edge of Latium. It is the low point of the second war.", certainty: "probable", war: "samnite-second" },
  { id: "e314", year: -314, toYear: -313, title: "The tide turns in Campania", summary: "Rome retakes the coast road, storms the towns that had defected, and plants colonies at Luceria and Saticula to hold the Apennine gaps from the far side.", certainty: "probable", war: "samnite-second" },
  { id: "e312", year: -312, title: "The Via Appia begun", summary: "A paved road is driven from Rome to Capua. It is built to move armies to the Samnite front in any weather, and it is the point at which Roman engineering becomes a weapon.", certainty: "attested", war: "samnite-second" },
  { id: "e311", year: -311, toYear: -306, title: "Etruria joins in, and is beaten", summary: "The Etruscan cities enter the war and are defeated at Lake Vadimon and elsewhere; Rome fights on two fronts and holds both.", certainty: "probable", war: "samnite-second" },
  { id: "e305", year: -305, title: "Bovianum taken and the war ends", summary: "The Samnite capital falls and Samnium accepts terms. Rome has taken twenty years to win, and the treaty leaves the federation intact.", certainty: "probable", war: "samnite-second" },

  { id: "e304", year: -304, toYear: -299, title: "The Apennines encircled", summary: "Rome makes treaties with the Marsi, Paeligni, Frentani and Picentes, ringing Samnium with allies. Colonies at Alba Fucens and Carsioli hold the high valleys.", certainty: "probable", war: "samnite-third" },
  { id: "e298", year: -298, toYear: -296, title: "The Third Samnite War", summary: "The last Samnite war begins, and this time Samnium builds a coalition: Etruscans, Umbrians and Gauls agree to attack Rome together.", certainty: "probable", war: "samnite-third" },
  { id: "e295", year: -295, title: "Sentinum", summary: "Rome meets a Samnite and Gallic army in Umbria in the largest battle fought in Italy before Cannae. A second Decius Mus devotes himself as his father had. The coalition is broken and never re-formed.", certainty: "probable", battleSlug: "sentinum", war: "samnite-third" },
  { id: "e294", year: -294, title: "The war carried into Samnium", summary: "Rome invades the Samnite heartland from several directions at once, a strategy the earlier wars had never managed.", certainty: "probable", war: "samnite-third" },
  { id: "e293", year: -293, title: "Aquilonia", summary: "A Samnite army raised under an oath sworn in a covered enclosure is destroyed. Livy's account of the ritual is unusually detailed and unusually hard to check.", certainty: "traditional", battleSlug: "aquilonia", war: "samnite-third" },
  { id: "e292", year: -292, toYear: -291, title: "Samnium submits", summary: "Resistance ends and Samnium becomes an ally on Roman terms. Rome now holds or commands the peninsula from the Po to Lucania.", certainty: "probable", war: "samnite-third" },

  { id: "e290", year: -290, toYear: -285, title: "The Sabines annexed, and the north secured", summary: "Sabine territory is taken outright and its people given citizenship rather than a treaty. The colony at Hadria carries Rome to the Adriatic coast.", certainty: "probable", war: "pyrrhic-war" },
  { id: "e284", year: -284, toYear: -283, title: "The Gauls beaten at Lake Vadimon", summary: "A Senonian and Etruscan army is destroyed at Lake Vadimon and the ager Gallicus on the Adriatic coast is annexed, with a colony planted at Sena Gallica to hold it. The Gallic threat that began at the Allia is ended for a century.", certainty: "probable", war: "pyrrhic-war" },
  { id: "e282", year: -282, toYear: -281, title: "The Tarentine crisis", summary: "A Roman squadron enters the gulf of Taranto in breach of an old agreement and is attacked. Tarentum, unwilling to face Rome with its own citizen levy, hires a professional: Pyrrhus, king of Epirus and the most admired soldier of the age.", certainty: "probable", war: "pyrrhic-war" },
  { id: "e280", year: -280, title: "Heraclea", summary: "Pyrrhus lands with a Hellenistic army — pike phalanx, Thessalian cavalry, twenty elephants — and beats Rome in its first battle against troops of that kind. The elephants decide it; the Romans had never seen one.", certainty: "probable", battleSlug: "heraclea", war: "pyrrhic-war" },
  { id: "e279", year: -279, title: "Asculum", summary: "Pyrrhus wins again and cannot afford to. The losses among his own officers and veterans, against a Rome that simply enrolls another army, are the origin of the phrase.", certainty: "probable", battleSlug: "asculum", war: "pyrrhic-war" },
  { id: "e278", year: -278, toYear: -276, title: "Pyrrhus in Sicily", summary: "Rome refuses to negotiate while he stands on Italian soil, so Pyrrhus crosses to Sicily against Carthage instead, takes almost the whole island, fails at Lilybaeum, and alienates the Greek cities he came to protect. Rome and Carthage sign a treaty against him.", certainty: "probable", war: "pyrrhic-war" },
  { id: "e275", year: -275, title: "Beneventum", summary: "Back in Italy, Pyrrhus is fought to a standstill near Malventum — the town Rome renamed Beneventum afterwards. He returns to Epirus, and the professional army of the Hellenistic world has been beaten by a militia that could replace its losses.", certainty: "probable", battleSlug: "beneventum", war: "pyrrhic-war" },
  { id: "e274", year: -274, toYear: -273, title: "The south left without a protector", summary: "With Pyrrhus gone the Greek cities have no one to call on. Rome moves against Tarentum, and Ptolemaic Egypt opens diplomatic relations — the first Hellenistic kingdom to treat Rome as a power.", certainty: "probable", war: "pyrrhic-war" },
  { id: "e272", year: -272, title: "Tarentum falls", summary: "The greatest Greek city in Italy surrenders its walls and its fleet. Rome now holds the whole peninsula.", certainty: "probable", battleSlug: "tarentum", war: "pyrrhic-war" },

  { id: "e271", year: -271, toYear: -270, title: "The Rhegium garrison destroyed", summary: "A Roman legion that had seized Rhegium for itself years earlier is besieged by its own state, taken, and its survivors flogged and beheaded in the Forum. Rome had just demonstrated to every Italian city what Roman discipline meant.", certainty: "probable", war: "italian-unification" },
  { id: "e269", year: -269, toYear: -266, title: "Italy made into one military system", summary: "The last resisting communities of the south and of Etruria come in. Rome now has a network of colonies, roads and unequal alliances that can put more men in the field than any state in the western Mediterranean.", certainty: "probable", war: "italian-unification" },
  { id: "e265", year: -265, title: "Volsinii, and the eve of the Punic wars", summary: "The last independent Etruscan city asks Rome to put down its own rebellious underclass. The siege runs into the following year and ends with Volsinii destroyed and resettled — and in that same year the Mamertines of Messana make a similar appeal from across the strait, and Rome crosses to Sicily.", certainty: "probable", war: "italian-unification" },
];

const firstPunicEvents: HistoricalEvent[] = [
  { id: "e264", year: -264, title: "Rome crosses to Sicily", summary: "Roman intervention at Messana expands into open war with Carthage.", certainty: "attested", battleSlug: "messana" },
  { id: "e263", year: -263, title: "Syracuse changes sides", summary: "Hiero II reaches terms with Rome, strengthening Roman logistics in Sicily.", certainty: "attested" },
  { id: "e262", year: -262, title: "Agrigentum invested", summary: "Roman armies begin the war’s first great siege.", certainty: "attested", battleSlug: "agrigentum" },
  { id: "e261", year: -261, title: "Agrigentum falls", summary: "Rome captures Akragas after defeating a Carthaginian relief force.", certainty: "attested", battleSlug: "agrigentum" },
  { id: "e260", year: -260, title: "A naval power emerges", summary: "Duilius wins Rome’s first major sea victory at Mylae.", certainty: "attested", battleSlug: "mylae" },
  { id: "e259", year: -259, title: "War widens", summary: "Operations extend toward Sardinia and Corsica; surviving accounts are fragmentary.", certainty: "probable" },
  { id: "e258", year: -258, title: "Fighting near Sulci", summary: "A Roman fleet wins a poorly documented encounter off Sardinia.", certainty: "disputed", battleSlug: "sulci" },
  { id: "e257", year: -257, title: "Clash at Tyndaris", summary: "A sudden engagement off northern Sicily ends without decisive strategic change.", certainty: "probable", battleSlug: "tyndaris" },
  { id: "e256", year: -256, title: "The war crosses to Africa", summary: "Victory at Ecnomus enables a Roman landing near Aspis.", certainty: "attested", battleSlug: "cape-ecnomus" },
  { id: "e255", year: -255, title: "Regulus defeated", summary: "After success at Adys, the Roman expedition is destroyed on the Bagradas plain.", certainty: "attested", battleSlug: "bagradas" },
  { id: "e254", year: -254, title: "Panormus captured", summary: "Roman forces take the major north-Sicilian port.", certainty: "attested" },
  { id: "e253", year: -253, title: "Costly maritime campaigning", summary: "Roman operations on the African coast are followed by another destructive storm.", certainty: "probable" },
  { id: "e252", year: -252, title: "Pressure on western Sicily", summary: "Roman advances narrow the Carthaginian position in Sicily.", certainty: "probable" },
  { id: "e251", year: -251, title: "War of positions", summary: "Both sides maneuver around the remaining Carthaginian strongholds.", certainty: "probable" },
  { id: "e250", year: -250, title: "Panormus and Lilybaeum", summary: "Rome wins at Panormus and begins the long siege of Lilybaeum.", certainty: "attested", battleSlug: "panormus" },
  { id: "e249", year: -249, title: "Disaster at Drepana", summary: "Adherbal defeats a Roman fleet attempting a surprise attack.", certainty: "attested", battleSlug: "drepana" },
  { id: "e248", year: -248, title: "The siege continues", summary: "Lilybaeum remains supplied by sea despite Roman pressure.", certainty: "attested", battleSlug: "lilybaeum" },
  { id: "e247", year: -247, title: "Hamilcar takes command", summary: "Hamilcar Barca begins operations from the heights near Panormus.", certainty: "attested" },
  { id: "e246", year: -246, title: "Stalemate in western Sicily", summary: "Raids and positional warfare replace large set-piece battles.", certainty: "probable" },
  { id: "e245", year: -245, title: "Mount Eryx contested", summary: "Carthaginian and Roman forces struggle over positions commanding Drepana.", certainty: "probable" },
  { id: "e244", year: -244, title: "A war of endurance", summary: "Neither side can force a decision around the western ports.", certainty: "probable" },
  { id: "e243", year: -243, title: "Rome finances a new fleet", summary: "Private contributions support construction of a renewed Roman navy.", certainty: "attested" },
  { id: "e242", year: -242, title: "Blockade tightens", summary: "The new Roman fleet drills and restricts Carthaginian access to western Sicily.", certainty: "probable" },
  { id: "e241", year: -241, title: "Victory at the Aegates", summary: "Rome defeats the relief fleet; peace ends the First Punic War.", certainty: "attested", battleSlug: "aegates" },
];

// Every year between the wars carries its own entry: the decades after 241 are
// where the second war was made, and a blank "year in focus" told the reader
// nothing was happening when a great deal was.
const interbellumEvents: HistoricalEvent[] = [
  { id: "e240", year: -240, title: "The Mercenary War", summary: "Carthage’s unpaid mercenaries and Libyan subjects revolt in a brutal war fought for survival at home.", certainty: "attested", war: "interbellum" },
  { id: "e239", year: -239, title: "Revolt spreads through Libya", summary: "Utica and Hippacra join the rebels. Carthage is besieged in its own hinterland and Hamilcar is recalled to command.", certainty: "attested", war: "interbellum" },
  { id: "e238", year: -238, title: "Rome seizes Sardinia", summary: "The mercenary garrison of Sardinia offers the island to Rome, which takes it and raises the indemnity when Carthage protests.", certainty: "attested", war: "interbellum" },
  { id: "e237", year: -237, title: "The Barcids enter Iberia", summary: "With the revolt crushed, Hamilcar Barca crosses to Iberia to build a Carthaginian power base beyond Roman reach.", certainty: "attested", war: "interbellum" },
  { id: "e236", year: -236, title: "Hamilcar campaigns in the south", summary: "Operations from Gades bring the Turdetani and the silver of the Guadalquivir under Carthaginian control.", certainty: "probable", war: "interbellum" },
  { id: "e235", year: -235, title: "Rome closes the temple of Janus", summary: "For the first time in living memory Rome is formally at peace, while Carthaginian power grows in Iberia.", certainty: "probable", war: "interbellum" },
  { id: "e234", year: -234, title: "Silver and soldiers", summary: "Iberian mines pay the indemnity to Rome and fund an army recruited and trained in Spain rather than hired abroad.", certainty: "probable", war: "interbellum" },
  { id: "e233", year: -233, title: "Rome fights the Sardinians", summary: "Roman consuls campaign against resistance in Sardinia and against Ligurian communities in the north.", certainty: "probable", war: "interbellum" },
  { id: "e232", year: -232, title: "Land for the landless", summary: "Rome distributes territory taken from the Gauls in the Ager Gallicus, hardening Cisalpine hostility.", certainty: "probable", war: "interbellum" },
  { id: "e231", year: -231, title: "Roman envoys in Spain", summary: "Rome reportedly sends an embassy to Hamilcar, who answers that he makes war on Iberians to pay Roman debts.", certainty: "disputed", war: "interbellum" },
  { id: "e230", year: -230, title: "Illyrian piracy", summary: "Attacks on Italian shipping in the Adriatic draw Roman attention east for the first time.", certainty: "probable", war: "interbellum" },
  { id: "e229", year: -229, title: "Hasdrubal succeeds Hamilcar", summary: "Hamilcar dies on campaign. His son-in-law Hasdrubal takes command, founds New Carthage, and rules by diplomacy as much as war.", certainty: "probable", war: "interbellum" },
  { id: "e228", year: -228, title: "First Illyrian War settled", summary: "Rome imposes terms on Queen Teuta and gains a foothold of allied cities on the far Adriatic shore.", certainty: "attested", war: "interbellum" },
  { id: "e227", year: -227, title: "Sicily and Sardinia become provinces", summary: "Rome appoints two additional praetors to govern its overseas possessions — the beginning of provincial administration.", certainty: "attested", war: "interbellum" },
  { id: "e226", year: -226, title: "The Ebro agreement", summary: "Rome and Hasdrubal reportedly fix the Ebro as the limit of Carthaginian expansion, leaving what lies south of it to Carthage.", certainty: "probable", war: "interbellum" },
  { id: "e225", year: -225, title: "Gauls invade Italy", summary: "A large Gallic army crosses the Apennines and is destroyed at Telamon in Etruria, caught between two Roman armies.", certainty: "attested", war: "interbellum" },
  { id: "e224", year: -224, title: "Rome pushes into the Po", summary: "Roman armies cross the Po and force the Boii to terms, carrying the war into Cisalpine Gaul itself.", certainty: "probable", war: "interbellum" },
  { id: "e223", year: -223, title: "Campaign against the Insubres", summary: "Flaminius campaigns beyond the Po; the Insubres are defeated but not yet broken.", certainty: "probable", war: "interbellum" },
  { id: "e222", year: -222, title: "Clastidium and Mediolanum", summary: "Marcellus kills a Gallic chief in single combat at Clastidium and Rome takes Mediolanum, completing the conquest of the Po valley.", certainty: "attested", war: "interbellum" },
  { id: "e221", year: -221, title: "Hannibal takes command", summary: "Hasdrubal is assassinated. The army in Spain acclaims Hannibal, then about twenty-six, and Carthage confirms him.", certainty: "attested", war: "interbellum" },
  { id: "e220", year: -220, title: "Tension over Saguntum", summary: "Hannibal campaigns to the Tagus and Duero while Roman envoys warn him away from Saguntum, a city south of the Ebro under Roman protection.", certainty: "probable", war: "interbellum" },
];

const secondPunicEvents: HistoricalEvent[] = [
  { id: "e219", year: -219, title: "Saguntum falls", summary: "Hannibal storms Saguntum; Rome demands his surrender and, refused, declares war.", certainty: "attested", battleSlug: "saguntum", war: "second-punic" },
  { id: "e218", year: -218, title: "Hannibal crosses the Alps", summary: "After Ticinus and Trebia, Hannibal is established in northern Italy.", certainty: "attested", battleSlug: "alps-crossing", war: "second-punic" },
  { id: "e217", year: -217, title: "Ambush at Lake Trasimene", summary: "Hannibal destroys Flaminius’ army; Rome appoints Fabius Maximus dictator.", certainty: "attested", battleSlug: "trasimene", war: "second-punic" },
  { id: "e216", year: -216, title: "Catastrophe at Cannae", summary: "A vast Roman army is encircled and destroyed; several Italian communities defect.", certainty: "attested", battleSlug: "cannae", war: "second-punic" },
  { id: "e215", year: -215, title: "The war widens", summary: "Capua defects, and Carthage allies with Macedon; the conflict spreads beyond Italy.", certainty: "probable", war: "second-punic" },
  { id: "e214", year: -214, title: "Sicily changes sides", summary: "Syracuse abandons its fifty-year alliance with Rome. Marcellus crosses to Sicily and storms Leontini, and a second front opens on the island.", certainty: "probable", war: "second-punic" },
  { id: "e213", year: -213, title: "Archimedes stops an assault", summary: "Marcellus attacks Syracuse by land and sea and is beaten off outright by the engines on the walls. Rome settles down to blockade.", certainty: "attested", battleSlug: "syracuse", war: "second-punic" },
  { id: "e212", year: -212, title: "Syracuse falls; Rome invests Capua", summary: "Syracuse is taken by escalade after two years and sacked; Roman armies seal Capua behind a double line; Tarentum is lost to Hannibal.", certainty: "attested", battleSlug: "syracuse", war: "second-punic" },
  { id: "e211", year: -211, title: "Capua retaken", summary: "Hannibal’s march on Rome fails to save Capua, which surrenders and is punished.", certainty: "attested", battleSlug: "capua", war: "second-punic" },
  { id: "e210", year: -210, title: "Scipio to Spain", summary: "The young Publius Cornelius Scipio takes command of the Roman effort in Iberia.", certainty: "probable", war: "second-punic" },
  { id: "e209", year: -209, title: "New Carthage stormed", summary: "Scipio captures the Barcid capital in a single assault, seizing its resources.", certainty: "attested", battleSlug: "new-carthage", war: "second-punic" },
  { id: "e208", year: -208, title: "Baecula", summary: "Scipio defeats Hasdrubal Barca, who nonetheless escapes toward Italy.", certainty: "probable", battleSlug: "baecula", war: "second-punic" },
  { id: "e207", year: -207, title: "Decision at the Metaurus", summary: "Hasdrubal’s relieving army is destroyed before it can reach Hannibal.", certainty: "attested", battleSlug: "metaurus", war: "second-punic" },
  { id: "e206", year: -206, title: "Ilipa clears Iberia", summary: "Scipio’s victory ends Carthaginian power in Spain.", certainty: "attested", battleSlug: "ilipa", war: "second-punic" },
  { id: "e205", year: -205, title: "Preparing for Africa", summary: "Elected consul, Scipio assembles an army in Sicily for an invasion of Africa.", certainty: "probable", war: "second-punic" },
  { id: "e204", year: -204, title: "Landing in Africa", summary: "Scipio crosses to Africa and, with Masinissa, campaigns near Utica.", certainty: "probable", war: "second-punic" },
  { id: "e203", year: -203, title: "The Great Plains", summary: "Scipio wins in the Bagradas valley; Carthage recalls Hannibal from Italy.", certainty: "attested", battleSlug: "great-plains", war: "second-punic" },
  { id: "e202", year: -202, title: "Zama decides the war", summary: "Scipio defeats Hannibal in Africa in the war’s final pitched battle.", certainty: "attested", battleSlug: "zama", war: "second-punic" },
  { id: "e201", year: -201, title: "Carthage accepts terms", summary: "Carthage surrenders its fleet and Iberia, pays a large indemnity, and is barred from war without Roman consent.", certainty: "attested", war: "second-punic" },
];

const macedonianEvents: HistoricalEvent[] = [
  { id: "e200", year: -200, title: "Rome turns east", summary: "Barely out of the war with Carthage, Rome declares war on Philip V of Macedon.", certainty: "attested", war: "macedonian-second" },
  { id: "e199", year: -199, title: "War in the passes", summary: "Roman forces probe Macedonia’s western frontier with little decisive result.", certainty: "probable", war: "macedonian-second" },
  { id: "e198", year: -198, title: "Breakthrough at the Aous", summary: "Flamininus forces the Aoös gorge and pushes Philip back into Thessaly.", certainty: "attested", battleSlug: "aous", war: "macedonian-second" },
  { id: "e197", year: -197, title: "Decision at Cynoscephalae", summary: "The legion defeats the phalanx; Philip sues for peace.", certainty: "attested", battleSlug: "cynoscephalae", war: "macedonian-second" },
  { id: "e196", year: -196, title: "Freedom of the Greeks", summary: "At the Isthmian Games, Flamininus proclaims the Greek cities free — under Roman oversight.", certainty: "attested", war: "macedonian-second" },
];

const seleucidEvents: HistoricalEvent[] = [
  { id: "e195", year: -195, title: "War on Nabis of Sparta", summary: "Before he can leave, Flamininus takes Rome and its Greek allies against the last independent power in the Peloponnese. Nabis loses Argos and the Laconian ports but keeps Sparta and his throne — a settlement that satisfies nobody and leaves the Achaeans to finish the job.", certainty: "attested", war: "greek-settlement" },
  { id: "e194", year: -194, title: "Rome leaves Greece", summary: "Flamininus withdraws every Roman garrison, including the three fortresses Philip had called the fetters of Greece — Demetrias, Chalcis and Acrocorinth — and sails home. It is the one moment Rome does exactly what it said it would do, and it leaves the fortresses open for the next army that wants them.", certainty: "attested", war: "greek-settlement" },
  { id: "e193", year: -193, title: "The embassies fail", summary: "Roman envoys at Ephesus tell Antiochus to keep out of Europe; his tell Rome to keep out of Asia. Neither will concede the principle, and the Aetolians, who believe Rome cheated them of their share of the Macedonian victory, begin looking for a king of their own.", certainty: "probable", war: "greek-settlement" },
  { id: "e192", year: -192, title: "Antiochus lands at Demetrias", summary: "Elected the Aetolians’ commander-in-chief, Antiochus crosses to Greece with about ten thousand men — expecting the Greeks to rise for him, and finding almost nobody does. He winters at Chalcis. Rome declares war.", certainty: "attested", war: "seleucid-war" },
  { id: "e191", year: -191, title: "Thrown out of Europe at Thermopylae", summary: "Acilius Glabrio attacks the pass frontally while Cato climbs Callidromus in the dark and comes down behind the Aetolian outposts holding the heights. Antiochus escapes to Ephesus with a few hundred men. In the autumn the Roman and Pergamene fleets beat his admiral Polyxenidas off Cape Corycus.", certainty: "attested", battleSlug: "thermopylae", war: "seleucid-war" },
  { id: "e190", year: -190, title: "Magnesia decides it", summary: "Hannibal, commanding a fleet for the only time in his life, is beaten by the Rhodians off the Eurymedon; Myonessus destroys the Seleucid fleet and opens the Hellespont; and the first Roman army ever to enter Asia breaks Antiochus at Magnesia under the walls of Sipylus.", certainty: "attested", battleSlug: "magnesia", war: "seleucid-war" },
  { id: "e189", year: -189, title: "Aetolia beaten, Galatia plundered", summary: "Ambracia falls after a siege fought partly underground, and the Aetolian League surrenders its independence in foreign policy. Meanwhile the consul Manlius Vulso marches into Galatia and storms the Celtic settlers on Mount Olympus and Magaba — a campaign for plunder that the Senate very nearly refused to honour.", certainty: "probable", war: "seleucid-war" },
  { id: "e188", year: -188, title: "The peace of Apamea", summary: "Antiochus abandons everything north and west of the Taurus, surrenders his elephants and all but ten warships, and undertakes to pay fifteen thousand talents over twelve years — the largest indemnity in ancient history. Rome annexes nothing: the ground goes to Pergamum and Rhodes, and the legions go home.", certainty: "attested", war: "seleucid-war" },
];

// The grain of these entries changes at 167, and it changes because the evidence
// does. Livy's fifth decade survives to that year and supports a year at a time;
// after it he is lost, and 166–150 is known from one-paragraph summaries. Those
// years are drawn as phases rather than invented as years.
const lateRepublicanEvents: HistoricalEvent[] = [
  { id: "e187", year: -187, toYear: -180, title: "The wars nobody counted", summary: "Rome is at war every year of this stretch and none of it has a name. Consular armies grind through Liguria and Istria; praetors fight annual campaigns in both Spanish provinces. It is the ordinary condition of the Republic, and it is invisible because nobody wrote it up as a war.", certainty: "probable", war: "western-wars" },
  { id: "e179", year: -179, title: "Perseus succeeds Philip V", summary: "Philip dies having spent twenty years rebuilding Macedon's revenues, mines and manpower under the terms Rome imposed in 196. His son inherits a kingdom stronger than the one Cynoscephalae defeated, and a Roman Senate that has noticed.", certainty: "attested", war: "western-wars" },
  { id: "e178", year: -178, toYear: -172, title: "The drift to war", summary: "Perseus rebuilds Macedon's standing in Greece by cancelling debts and taking in exiles — none of it forbidden, all of it read at Rome as preparation. In 172 Eumenes of Pergamum comes to the Senate in person to denounce him, and is nearly killed on the way home. Rome declares war.", certainty: "probable", war: "western-wars" },
  { id: "e171", year: -171, title: "Beaten at Callinicus", summary: "The first engagement of the war is a cavalry action outside Larissa, and Perseus wins it. He then offers terms on the same conditions he had before the battle, and Rome refuses them — a refusal that becomes the pattern of the next three years.", certainty: "attested", battleSlug: "callinicus", war: "macedonian-third" },
  { id: "e170", year: -170, title: "A war going nowhere", summary: "Two more consular years produce nothing but plundered allies and complaints in the Senate about how Roman commanders are treating the Greeks they came to liberate.", certainty: "probable", war: "macedonian-third" },
  { id: "e169", year: -169, title: "Stalled on the Elpeus", summary: "Marcius Philippus forces a way over the Olympus range and reaches the coastal plain, then finds Perseus entrenched behind the Elpeus and cannot shift him. The army winters within sight of a position it cannot attack.", certainty: "probable", war: "macedonian-third" },
  { id: "e168", year: -168, title: "Pydna", summary: "Aemilius Paullus turns the Elpeus line by sending a column over the mountain, and the two armies meet the next afternoon by accident while watering. The phalanx advances, the ground breaks it up, and the legions go into the gaps. The Antigonid kingdom ends in about an hour.", certainty: "attested", battleSlug: "pydna", war: "macedonian-third" },
  { id: "e167", year: -167, title: "The settlement, and what it cost", summary: "Macedon is abolished and cut into four republics forbidden to trade or intermarry with one another. Epirus, which had gone over to Perseus, is sacked to order: seventy towns destroyed and a hundred and fifty thousand people sold. A thousand Achaeans are deported to Italy without trial, and one of them is Polybius.", certainty: "attested", war: "after-pydna" },
  { id: "e166", year: -166, toYear: -155, title: "A generation with no rival", summary: "Rome has beaten every organised power in the Mediterranean and governs almost none of it. These years leave little narrative because Livy's account of them is lost: what the summaries record is embassies, arbitration, and a Senate settling other people's quarrels without sending an army.", certainty: "probable", war: "after-pydna" },
  { id: "e154", year: -154, toYear: -151, title: "Spain turns ugly", summary: "The Celtiberian and Lusitanian wars break the pattern. These are campaigns with no decisive battle to win, against peoples who will not stay beaten, and they become unpopular enough at Rome that in 151 the consul has to conscript by force and the tribunes gaol him for it.", certainty: "probable", war: "after-pydna" },
  { id: "e150", year: -150, title: "A massacre, and a pretender", summary: "Servius Sulpicius Galba accepts the surrender of three Lusitanian groups, disarms them, and has them killed — an act prosecuted at Rome and acquitted, and the reason Viriathus goes to war. In Macedonia a man claiming to be Perseus' son raises the country against the four republics.", certainty: "probable", war: "after-pydna" },
  { id: "e149", year: -149, title: "Carthage is told to move inland", summary: "Carthage finally fights back against Masinissa's encroachment, which the treaty of 201 forbids, and Rome declares war. The city gives up three hundred hostages and every weapon it has — and is then ordered to abandon the site and rebuild ten miles from the sea. It refuses, and rearms behind its walls.", certainty: "attested", battleSlug: "carthage", war: "punic-third" },
  { id: "e148", year: -148, title: "Macedonia becomes a province", summary: "Andriscus, who had beaten one Roman army, is destroyed by Metellus at a second battle near Pydna. Rome stops experimenting with client republics: Macedonia is annexed and given a governor, and with him the oversight of Greece.", certainty: "probable", war: "punic-third" },
  { id: "e147", year: -147, title: "Scipio Aemilianus takes command", summary: "Two years of mismanaged siege end when the Senate lets a man too young for the consulship hold it. Scipio seals the harbour with a mole, storms the last Carthaginian field army at Nepheris, and shuts the city in completely for the winter.", certainty: "probable", battleSlug: "nepheris", war: "punic-third" },
  { id: "e146", year: -146, title: "Carthage and Corinth", summary: "Carthage is taken street by street over six days, burned, and its site cursed; the survivors are sold. In the same summer Mummius sacks Corinth and dissolves the Achaean League. Rome ends the year with provinces in Africa and Macedonia and no rival anywhere — Polybius, watching the fire, records Scipio weeping and quoting Homer on the fall of Troy.", certainty: "attested", battleSlug: "carthage", war: "punic-third" },
];

// 145–100. The record thins again and does not recover: Polybius stops at 146 and
// Livy survives only as summaries, so most of these years are phases. The two
// exceptions are the Jugurthine war, which Sallust wrote a whole book about, and
// the Cimbric war, which Plutarch covers because Marius is the subject of a life.
const marianEvents: HistoricalEvent[] = [
  { id: "e145", year: -145, toYear: -140, title: "Viriathus holds Lusitania", summary: "A shepherd who survived a Roman massacre of his own people under truce made himself the commander of a war Rome could not win. For eight years he beat or evaded consular armies in country that suited him, and in 140 a Roman commander signed a treaty recognising him as a friend of the Roman people.", certainty: "probable", war: "iberian-wars" },
  { id: "e139", year: -139, title: "Viriathus murdered", summary: "The Senate refuses to ratify the treaty. Three of Viriathus' own envoys are bribed to kill him in his sleep, and when they come for their payment the Roman commander tells them Rome does not pay men who kill their own leaders — a line the sources preserve as though it settled the matter.", certainty: "probable", war: "iberian-wars" },
  { id: "e138", year: -138, toYear: -135, title: "Numantia beats four armies", summary: "The war moves to the Celtiberian plateau, where a hill town of perhaps eight thousand people defeats one Roman army after another. In 137 a consular army of twenty thousand is surrounded and surrenders, and the treaty its quaestor signs to save it — Tiberius Gracchus, in his first public act — is repudiated at Rome.", certainty: "probable", war: "iberian-wars" },
  { id: "e134", year: -134, title: "Scipio Aemilianus sent to Numantia", summary: "The man who took Carthage is given the command by special dispensation, arrives to find the army drunk and full of camp followers, throws them out, and refuses to fight at all. He builds a wall round the town instead.", certainty: "attested", battleSlug: "numantia", war: "iberian-wars" },
  { id: "e133", year: -133, title: "Numantia falls; Tiberius Gracchus killed", summary: "Numantia surrenders after eight months of starvation and is razed. In the same year Tiberius Gracchus is beaten to death in Rome by a mob of senators over a land bill, and Attalus III of Pergamum dies leaving his kingdom to the Roman people in his will.", certainty: "attested", battleSlug: "numantia", war: "iberian-wars" },
  { id: "e132", year: -132, toYear: -130, title: "Fighting for the bequest", summary: "Aristonicus, a claimant to the Attalid throne, refuses to be inherited and raises western Asia against Rome — freeing slaves to do it. It takes three years and a consul killed in the field to take possession of a kingdom that had been left to Rome in writing.", certainty: "probable", war: "gracchan-crisis" },
  { id: "e129", year: -129, title: "Asia becomes a province", summary: "The bequest is organised as the province of Asia, and its taxes are farmed out to Roman companies at auction. It is the richest thing Rome has ever governed and the first province acquired without a war to acquire it.", certainty: "attested", war: "gracchan-crisis" },
  { id: "e128", year: -128, toYear: -122, title: "The road to Spain", summary: "Rome conquers the coast of southern Gaul, largely to secure the land route to the Spanish provinces it already has. The Allobroges and the Arverni are beaten in 121, and a colony is planted at Narbo.", certainty: "probable", war: "gracchan-crisis" },
  { id: "e121", year: -121, title: "Gaius Gracchus killed, and a province in Gaul", summary: "The Senate passes its first emergency decree and three thousand of Gaius Gracchus' supporters are killed in Rome. In the same year the conquest of southern Gaul is completed, and the province that will be called Narbonensis gives Rome a road to Spain that does not need ships.", certainty: "attested", war: "gracchan-crisis" },
  { id: "e120", year: -120, toYear: -114, title: "Quiet, and a Numidian succession", summary: "Little that the summaries record. In Numidia, Micipsa dies leaving the kingdom to two sons and an adopted nephew, Jugurtha, who had commanded Numidian cavalry for Scipio at Numantia and had watched how Rome worked from inside the Roman camp.", certainty: "probable", war: "gracchan-crisis" },
  { id: "e113", year: -113, title: "Noreia: the Cimbri arrive", summary: "A people moving south out of Jutland meet a consular army in the eastern Alps and destroy it. Rome has met migrating peoples before; it has not met one it cannot make go away, and over the next eight years the Cimbri and the Teutones will beat five Roman armies.", certainty: "probable", battleSlug: "noreia", war: "jugurthine-war" },
  { id: "e112", year: -112, toYear: -110, title: "Jugurtha buys his way out, twice", summary: "Jugurtha takes Cirta and kills the Italian traders inside it, which forces a declaration of war. He then twice buys a settlement — once from a consul, once from a commission — and when summoned to Rome under safe conduct he has a rival claimant murdered in the city itself. Sallust makes these years the whole point of his book.", certainty: "probable", war: "jugurthine-war" },
  { id: "e109", year: -109, title: "Metellus takes the command", summary: "An honest and highly competent commander is finally sent, and the war changes character: no more negotiation, and a methodical reduction of Numidian towns. His legate is Gaius Marius.", certainty: "probable", war: "jugurthine-war" },
  { id: "e108", year: -108, title: "The Muthul", summary: "Jugurtha ambushes Metellus' army strung out on the march to water. The Romans fight their way clear and hold the field, which makes it a victory — and changes nothing, because Jugurtha's army withdraws intact and goes on doing exactly what it was doing.", certainty: "probable", battleSlug: "muthul", war: "jugurthine-war" },
  { id: "e107", year: -107, title: "Marius elected consul", summary: "Marius campaigns for the consulship by telling the assembly that the nobility cannot fight, wins it against every convention, and has the African command transferred to him by a vote of the people over the Senate's head. He then raises troops from men with no property, who had never been liable for service and had nothing to go back to.", certainty: "attested", war: "jugurthine-war" },
  { id: "e106", year: -106, title: "The war ground down", summary: "Marius takes the fortresses Metellus had left, including one on a rock said to be unclimbable, and pushes Jugurtha west into the country of his father-in-law Bocchus of Mauretania. The war is now about whether Bocchus will keep him.", certainty: "probable", war: "jugurthine-war" },
  { id: "e105", year: -105, title: "Arausio, and the end of Jugurtha", summary: "Bocchus is persuaded to hand Jugurtha over, and Marius' quaestor Sulla takes the surrender in person — the beginning of a quarrel that will end in civil war. Weeks later, on the Rhône, two Roman armies that refuse to cooperate are destroyed by the Cimbri with their backs to the river. The reported loss of eighty thousand is the worst since Cannae.", certainty: "attested", battleSlug: "arausio", war: "jugurthine-war" },
  { id: "e104", year: -104, title: "Marius rebuilds the army", summary: "Elected consul in his absence and then re-elected every year until the war is over, Marius spends two seasons drilling rather than fighting: baggage carried by the men, the eagle as the single standard of the legion, service by enlistment rather than by property. The Cimbri, meanwhile, have gone to Spain.", certainty: "probable", war: "cimbric-war" },
  { id: "e103", year: -103, title: "Waiting, and a canal", summary: "Still refusing battle, Marius has his army dig a canal from the Rhône to the sea to supply itself — the fossae Marianae — and watches the Teutones and Cimbri agree to invade Italy by two separate routes. Splitting is the mistake he has been waiting for.", certainty: "probable", war: "cimbric-war" },
  { id: "e102", year: -102, title: "Aquae Sextiae", summary: "Marius lets the Teutones march past his camp for six days, follows them, and destroys them in a two-day action in which a detachment hidden behind them attacks the rear at the moment of contact.", certainty: "attested", battleSlug: "aquae-sextiae", war: "cimbric-war" },
  { id: "e101", year: -101, title: "Vercellae", summary: "The Cimbri, who have crossed the Alps into the Po valley and beaten the other consul's army out of their way, are destroyed on the Raudian plain in high summer heat by an army that had chosen the ground and the hour.", certainty: "attested", battleSlug: "vercellae", war: "cimbric-war" },
  { id: "e100", year: -100, title: "The bill for the army comes in", summary: "Marius' veterans have no land, and the tribune who tries to give them some is killed in the Senate house with Marius' consent. The precedent set is the one that matters: an army enlisted for pay and discharged with nothing will look to its commander, not the state, and every commander after Marius knows it.", certainty: "probable", war: "cimbric-war" },
];

export const historicalEvents: HistoricalEvent[] = [
  ...earlyRepublicEvents,
  ...firstPunicEvents.map((event) => ({ ...event, war: "first-punic" })),
  ...interbellumEvents,
  ...secondPunicEvents,
  ...macedonianEvents,
  ...seleucidEvents,
  ...lateRepublicanEvents,
  ...marianEvents,
];
